import * as THREE from "three";

export class ChunkLoader {
  constructor(scene) {
    this.scene = scene;
    this.loaded = new Map();
  }

  async loadChunk(minx, miny, maxx, maxy) {
    const key = `${Math.round(minx)},${Math.round(miny)},${Math.round(
      maxx
    )},${Math.round(maxy)}`;
    if (this.loaded.has(key)) {
      console.log(`[ChunkLoader] Chunk ${key} already loaded`);
      return;
    }

    console.log(`[ChunkLoader] Loading chunk ${key} from server...`);
    if (!this.loaded.has(key))
      console.log(`[ChunkLoader] Loading chunk ${key}`);

    const url = `http://127.0.0.1:8000/chunk?minx=${minx}&miny=${miny}&maxx=${maxx}&maxy=${maxy}&simplify=1.0`;
    //const url = "http://127.0.0.1:8000/test_chunk";
    let geojson;
    try {
      const res = await fetch(url);
      if (!res.ok) {
        console.warn(
          `[ChunkLoader] HTTP error for chunk ${key}: ${res.status}`
        );
        return;
      }

      geojson = await res.json();
      if (!geojson.features || !Array.isArray(geojson.features)) {
        console.warn(`[ChunkLoader] Invalid GeoJSON for chunk ${key}`);
        return;
      }
    } catch (err) {
      console.error(`[ChunkLoader] Failed to load chunk ${key}:`, err);
      return;
    }

    console.log(`[ChunkLoader] Received ${geojson.features.length} features`);

    if (geojson.features.length === 0) {
      console.log(`[ChunkLoader] Chunk ${key} is empty, skipping`);
      return;
    }

    const group = this.geoJSONToMesh(geojson);
    console.log(
      `[ChunkLoader] Created ${group.children.length} meshes for chunk ${key}`
    );

    group.position.set((minx + maxx) / 2, 0, (miny + maxy) / 2);
    this.scene.add(group);
    this.loaded.set(key, group);

    console.log(`[ChunkLoader] Chunk ${key} added to scene`);
  }

  geoJSONToMesh(geojson) {
    const group = new THREE.Group();

    for (const f of geojson.features) {
      const geom = f.geometry;

      if (geom.type === "Polygon") {
        const mesh = this.createPolygonMesh(geom.coordinates);
        group.add(mesh);
      }

      if (geom.type === "MultiPolygon") {
        for (const poly of geom.coordinates) {
          const mesh = this.createPolygonMesh(poly);
          group.add(mesh);
        }
      }
    }

    return group;
  }

  createPolygonMesh(rings) {
    const shape = new THREE.Shape();
    const [outer, ...holes] = rings;

    outer.forEach(([x, y], i) => {
      if (i === 0) shape.moveTo(x, y);
      else shape.lineTo(x, y);
    });

    holes.forEach((holeCoords) => {
      const hole = new THREE.Path();
      holeCoords.forEach(([x, y], i) => {
        if (i === 0) hole.moveTo(x, y);
        else hole.lineTo(x, y);
      });
      shape.holes.push(hole);
    });

    const geometry = new THREE.ShapeGeometry(shape);
    const material = new THREE.MeshStandardMaterial({
      color: 0x66ccff,
      side: THREE.DoubleSide,
    });

    return new THREE.Mesh(geometry, material);
  }
}
