"use client";

import { useEffect, useRef } from "react";
import * as THREE from "three";
import proj4 from "proj4";
import { createRenderer } from "./three/Renderer";
import { createCamera } from "./three/Camera";
import { createScene } from "./three/Scene";
import { createControls } from "./three/Controls";
import { setupRaycast } from "./three/Raycast";
import { ChunkLoader } from "./three/ChunkLoader";

export default function ThreeScene({ settings }) {
  const ref = useRef(null);

  useEffect(() => {
    const container = ref.current;

    const renderer = createRenderer(container);
    const camera = createCamera(container.clientWidth, container.clientHeight);
    const { scene, cube } = createScene();
    const controls = createControls(camera, renderer.domElement);
    const cleanupRaycast = setupRaycast(
      renderer.domElement,
      camera,
      scene,
      controls,
      container
    );

    const loader = new ChunkLoader(scene);

    // EPSG:4326 → EPSG:3857
    const wgs84 = "EPSG:4326";
    const webMercator = "EPSG:3857";
    function toMercator(lon, lat) {
      return proj4(wgs84, webMercator, [lon, lat]);
    }

    async function updateChunks() {
      const target = controls.target;

      // Конвертируем координаты центра камеры в метры
      const [cx, cz] = toMercator(target.x, target.z);

      const size = 500; // размер чанка в метрах
      const minx = cx - size;
      const miny = cz - size;
      const maxx = cx + size;
      const maxy = cz + size;

      await loader.loadChunk(minx, miny, maxx, maxy);
    }

    controls.addEventListener("change", updateChunks);
    updateChunks();

    let frame;
    const loop = () => {
      cube.rotation.x += 0.01;
      cube.rotation.y += 0.01;

      controls.update();
      renderer.render(scene, camera);
      frame = requestAnimationFrame(loop);
    };
    loop();

    const handleResize = () => {
      renderer.setSize(container.clientWidth, container.clientHeight);
      camera.aspect = container.clientWidth / container.clientHeight;
      camera.updateProjectionMatrix();
    };
    window.addEventListener("resize", handleResize);

    return () => {
      cancelAnimationFrame(frame);
      controls.removeEventListener("change", updateChunks);
      window.removeEventListener("resize", handleResize);
      cleanupRaycast();

      container.removeChild(renderer.domElement);
      renderer.dispose();
      cube.geometry.dispose();
    };
  }, []);

  return <div ref={ref} className="w-full h-full" />;
}
